import json
import sys
print(json.dumps({'recursion_limit': sys.getrecursionlimit(), 'recursion_error_bases': [cls.__name__ for cls in RecursionError.__mro__]}))
for depth in (2000, 50000):
    try:
        value = json.loads('[' * depth + '0' + ']' * depth)
    except Exception as error:
        print(json.dumps({'depth': depth, 'exception': type(error).__name__, 'message': str(error)}))
    else:
        print(json.dumps({'depth': depth, 'parsed_type': type(value).__name__}))
PY"

